import { randomUUID } from 'node:crypto';
import { rmSync } from 'node:fs';
import { afterAll, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { pino } from 'pino';
import { buildApp } from '../src/app.js';
import type { Advisory } from '../src/core/types.js';
import { loadConfig } from '../src/util/config.js';

const DATA_PATHS: string[] = [];

/** Build an app with its own store file and an indexed vulnerable artifact. */
async function appWith(
  advisories: Advisory[]
): Promise<{ app: FastifyInstance; artifactId: string }> {
  const DATA_PATH = `./data/test-scans-${randomUUID()}.json`;
  DATA_PATHS.push(DATA_PATH);
  const config = loadConfig({ NODE_ENV: 'test', DATA_PATH });
  const app = buildApp({ config, logger: pino({ level: 'silent' }), advisories });
  await app.ready();

  const artifactId = randomUUID();
  await app.store.artifacts.create({
    id: artifactId,
    name: 'shop',
    version: '1.0.0',
    ecosystem: 'npm',
    dependencies: [{ name: 'log4jira', version: '2.10.0' }],
    createdAt: '2026-09-01T00:00:00.000Z',
  });
  return { app, artifactId };
}

afterAll(() => {
  for (const path of DATA_PATHS) rmSync(path, { force: true });
});

describe('POST /scans', () => {
  it('returns 503 and records nothing when advisory data is unavailable (OZ-107)', async () => {
    const { app, artifactId } = await appWith([]);
    const res = await app.inject({ method: 'POST', url: '/scans', payload: { artifactId } });

    expect(res.statusCode).toBe(503);
    expect(res.json()).toMatchObject({ error: 'AdvisoryDataUnavailable' });
    expect(await app.store.scans.list()).toEqual([]);
    await app.close();
  });

  it('scans normally when advisory data is present', async () => {
    const advisories: Advisory[] = [
      { id: 'A-1', package: 'log4jira', range: '<2.16.0', severity: 'critical', title: 'RCE' },
    ];
    const { app, artifactId } = await appWith(advisories);
    const res = await app.inject({ method: 'POST', url: '/scans', payload: { artifactId } });

    expect(res.statusCode).toBe(201);
    expect(res.json()).toMatchObject({ verdict: 'block' });
    expect(await app.store.scans.list()).toHaveLength(1);
    await app.close();
  });
